@pytest.mark.parametrize('deleted', [False, True]) @pytest.mark.parametrize('receipt_present', [False, True]) def test_unknown_receipt_reconciles_after_trigger_revocation(tmp_path, monkeypatch, deleted, receipt_present): """Revocation blocks new side effects, not lookup of the original receipt.""" monkeypatch.setattr(worker, '_wake_worker', AsyncMock()) async def run(): svc = Service(tmp_path/'automation', worker, AsyncMock(return_value={'ok': True})) await svc.start() try: adapter = bind(svc) svc.engine.actions.put('actions', action(['approved-target'])) spec = {**trigger('selected'), 'eventTypes': ['pan.interaction.responded']} svc.ledger.put(spec, 0, True) store = InteractionStore(tmp_path/'cards.sqlite') user = UserPrincipal('user') card = store.create({'ownerSessionId': 'source', 'recipientId': 'user', 'requestKey': 'receipt', 'card': {'title': 'choice', 'body': 'body', 'choices': [{'id': 'go', 'label': 'Go', 'triggerRef': {'id': 'selected', 'revision': 1}}]}}) store.respond(user, card['id'], {'requestId': 'once', 'expectedRevision': 0, 'choiceId': 'go'}) append = svc.events.append def commit_then_raise(*args): append(*args) raise OSError('receipt lost after EventStore commit') monkeypatch.setattr(svc.events, 'append', commit_then_raise) assert (await store.dispatch(user, card['id'], adapter))['delivery']['state'] == 'unknown' svc.ledger.put({**spec, 'enabled': False}, 1, True) def forbidden_append(*args): pytest.fail('Unknown must never append again') monkeypatch.setattr(svc.events, 'append', forbidden_append) if deleted: store.delete(user, card['id']) lookup = adapter.lookup lookups = [] async def original_receipt(eid): lookups.append(eid) return await lookup(eid) if receipt_present else None async def forbidden(*args): pytest.fail('Unknown must neither authorize current Trigger nor admit') adapter.lookup = original_receipt adapter.authorize = adapter.accept = forbidden reopened = InteractionStore(store.path) for _ in range(2): if deleted: await reopened.recover_detached(adapter) with reopened.db() as db: state = json.loads(db.execute('SELECT delivery FROM detached_deliveries').fetchone()[0])['state'] else: state = (await reopened.dispatch(user, card['id'], adapter))['delivery']['state'] assert state == ('accepted' if receipt_present else 'unknown') assert len(lookups) == (1 if receipt_present else 2) assert len(set(lookups)) == 1 assert len(svc.events.page()['events']) == 1 finally: await svc.close() > asyncio.run(run())
